4.4.3 Thanh ghi có Tín hiệu Cho phép (Enabled Registers)
Các thanh ghi có tín hiệu cho phép (enabled registers) chỉ phản hồi theo xung nhịp đồng hồ khi tín hiệu cho phép (enable) được kích hoạt. Ví dụ HDL 4.19 minh họa một thanh ghi có tín hiệu cho phép và có khả năng reset bất đồng bộ, thanh ghi này sẽ giữ nguyên giá trị cũ nếu cả hai tín hiệu reset và en đều ở mức FALSE.

Ví dụ HDL 4.19 THANH GHI CÓ TÍN HIỆU CHO PHÉP VÀ RESET DƯỢC

SystemVerilog
module flopenr(input logic clk,
               input logic reset,
               input logic en,
               input logic [3:0] d,
               output logic [3:0] q);

  // reset bất đồng bộ
  always_ff @(posedge clk, posedge reset)
    if (reset) q <= 4'b0;
    else if (en) q <= d;
endmodule

VHDL
library IEEE; use IEEE.STD_LOGIC_1164.all;

entity flopenr is
  port(clk,
       reset,
       en: in STD_LOGIC;
       d: in STD_LOGIC_VECTOR(3 downto 0);
       q: out STD_LOGIC_VECTOR(3 downto 0));
end;

architecture asynchronous of flopenr is
  -- reset bất đồng bộ
begin
  process(clk, reset) begin
    if reset then
      q <= "0000";
    elsif rising_edge(clk) then
      if en then
        q <= d;
      end if;
    end if;
  end process;
end;

