### 4.8 CÁC MODULE THAM SỐ HÓA (PARAMETERIZED MODULES)*

Cho đến nay, tất cả các module của chúng ta đều có độ rộng đầu vào và đầu ra cố định. Ví dụ, chúng ta đã phải định nghĩa các module riêng biệt cho các bộ dồn kênh 2:1 rộng 4-bit và 8-bit. Các ngôn ngữ HDL cho phép độ rộng bit thay đổi bằng cách sử dụng các module tham số hóa.

Ví dụ HDL 4.34 khai báo một bộ dồn kênh 2:1 tham số hóa với độ rộng mặc định là 8, sau đó sử dụng nó để tạo ra các bộ dồn kênh 4:1 rộng 8-bit và 12-bit.

216 CHƯƠNG BỐN Ngôn ngữ Mô tả Phần cứng

Ví dụ HDL 4.34 BỘ DỒN KÊNH 2:1 N-BIT ĐƯỢC THAM SỐ HÓA

SystemVerilog
module mux2
#(parameter width = 8)
  (input logic [width-1:0] d0, d1,
   input logic s,
   output logic [width-1:0] y);

  assign y = s ? d1 : d0;
endmodule

SystemVerilog cho phép sử dụng câu lệnh #(parameter...) trước các tín hiệu đầu vào và đầu ra để định nghĩa tham số. Câu lệnh parameter bao gồm một giá trị mặc định (8) của tham số, trong trường hợp này được gọi là width. Số lượng bit của các tín hiệu đầu vào và đầu ra có thể phụ thuộc vào tham số này.

module mux4_8(input logic [7:0] d0, d1, d2, d3,
               input logic [1:0] s,
               output logic [7:0] y);

  logic [7:0] low, hi;

  mux2 lowmux(d0, d1, s[0], low);
  mux2 himux(d2, d3, s[0], hi);
  mux2 outmux(low, hi, s[1], y);
endmodule

Bộ dồn kênh 4:1 8-bit khởi tạo ba bộ dồn kênh 2:1 bằng cách sử dụng độ rộng mặc định của chúng.
Ngược lại, một bộ dồn kênh 4:1 12-bit, mux4_12, sẽ cần phải ghi đè độ rộng mặc định bằng cách sử dụng ký hiệu #( ) trước tên thể hiện (instance name), như được hiển thị bên dưới.

module mux4_12(input logic [11:0] d0, d1, d2, d3,
                input logic [1:0] s,
                output logic [11:0] y);

  logic [11:0] low, hi;

  mux2 #(12) lowmux(d0, d1, s[0], low);
  mux2 #(12) himux(d2, d3, s[0], hi);
  mux2 #(12) outmux(low, hi, s[1], y);
endmodule

Đừng nhầm lẫn việc sử dụng dấu # biểu thị độ trễ (delay) với việc sử dụng #(...) trong việc định nghĩa và ghi đè tham số.

VHDL
library IEEE; use IEEE.STD_LOGIC_1164.all;

entity mux2 is
  generic(width: integer := 8);
  port(d0,
       d1: in STD_LOGIC_VECTOR(width-1 downto 0);
       s: in STD_LOGIC;
       y: out STD_LOGIC_VECTOR(width-1 downto 0));
end;

architecture synth of mux2 is
begin
  y <= d1 when s else d0;
end;

Câu lệnh generic bao gồm một giá trị mặc định (8) của width. Giá trị này là một số nguyên (integer).

library IEEE; use IEEE.STD_LOGIC_1164.all;

entity mux4_8 is
  port(d0, d1, d2,
       d3: in STD_LOGIC_VECTOR(7 downto 0);
       s: in STD_LOGIC_VECTOR(1 downto 0);
       y: out STD_LOGIC_VECTOR(7 downto 0));
end;

architecture struct of mux4_8 is
  component mux2
    generic(width: integer := 8);
    port(d0,
         d1: in STD_LOGIC_VECTOR(width-1 downto 0);
         s: in STD_LOGIC;
         y: out STD_LOGIC_VECTOR(width-1 downto 0));
  end component;
  signal low, hi: STD_LOGIC_VECTOR(7 downto 0);
begin
  lowmux: mux2 port map(d0, d1, s(0), low);
  himux: mux2 port map(d2, d3, s(0), hi);
  outmux: mux2 port map(low, hi, s(1), y);
end;

Bộ dồn kênh 4:1 8-bit, mux4_8, khởi tạo ba bộ dồn kênh 2:1 bằng cách sử dụng độ rộng mặc định của chúng.
Ngược lại, một bộ dồn kênh 4:1 12-bit, mux4_12, sẽ cần phải ghi đè độ rộng mặc định bằng cách sử dụng generic map, như được hiển thị bên dưới.

lowmux: mux2 generic map(12)
            port map(d0, d1, s(0), low);
himux: mux2 generic map(12)
            port map(d2, d3, s(0), hi);
outmux: mux2 generic map(low, hi, s(1), y);

