Các bài tập sau có thể được thực hiện bằng ngôn ngữ HDL mà bạn yêu thích. Nếu bạn có sẵn trình mô phỏng, hãy kiểm tra thiết kế của bạn. In các dạng sóng và giải thích cách chúng chứng minh rằng thiết kế hoạt động đúng. Nếu bạn có sẵn công cụ tổng hợp, hãy tổng hợp mã nguồn của bạn. In sơ đồ mạch được tạo ra và giải thích tại sao nó khớp với kỳ vọng của bạn.

Bài tập 4.1 Vẽ sơ đồ nguyên lý của mạch được mô tả bởi đoạn mã HDL sau. Tối giản sơ đồ sao cho nó hiển thị số lượng cổng logic tối thiểu.

SystemVerilog:
module exercise1(input logic a, b, c,
                 output logic y, z);

  assign y = a & b & c | a & b & ~c | a & ~b & c;
  assign z = a & b | ~a & ~b;
endmodule

VHDL:
library IEEE; use IEEE.STD_LOGIC_1164.all;

entity exercise1 is
  port(a, b, c: in  STD_LOGIC;
       y, z:    out STD_LOGIC);
end;

architecture synth of exercise1 is
begin
  y <= (a and b and c) or (a and b and not c) or
       (a and not b and c);
  z <= (a and b) or (not a and not b);
end;

Bài tập 4.2 Vẽ sơ đồ nguyên lý của mạch được mô tả bởi đoạn mã HDL sau. Tối giản sơ đồ sao cho nó hiển thị số lượng cổng logic tối thiểu.

SystemVerilog:
module exercise2(input  logic [3:0] a,
                 output logic [1:0] y);
  always_comb
    if      (a[0]) y = 2'b11;
    else if (a[1]) y = 2'b10;
    else if (a[2]) y = 2'b01;
    else if (a[3]) y = 2'b00;
    else           y = a[1:0];
endmodule

VHDL:
library IEEE; use IEEE.STD_LOGIC_1164.all;

entity exercise2 is
  port(a: in  STD_LOGIC_VECTOR(3 downto 0);
       y: out STD_LOGIC_VECTOR(1 downto 0));
end;

architecture synth of exercise2 is
begin
  process(all) begin
    if    a(0) then y <= "11";
    elsif a(1) then y <= "10";
    elsif a(2) then y <= "01";
    elsif a(3) then y <= "00";
    else            y <= a(1 downto 0);
    end if;
  end process;
end;

