Bài tập 4.24 Vẽ sơ đồ chuyển trạng thái cho máy trạng thái hữu hạn (FSM) được mô tả bởi đoạn mã HDL dưới đây.

SystemVerilog:
module fsm2(input logic clk, reset,
            input logic a, b,
            output logic y);

  logic [1:0] state, nextstate;

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  always_ff @(posedge clk, posedge reset)
    if (reset) state <= S0;
    else state <= nextstate;

  always_comb
    case (state)
      S0: if (a ^ b) nextstate = S1;
          else nextstate = S0;
      S1: if (a & b) nextstate = S2;
          else nextstate = S0;
      S2: if (a | b) nextstate = S3;
          else nextstate = S0;
      S3: if (a | b) nextstate = S3;
          else nextstate = S0;
    endcase

  assign y = (state == S1) | (state == S2);
endmodule

VHDL:
library IEEE; use IEEE.STD_LOGIC_1164.all;

entity fsm2 is
  port(clk, reset: in STD_LOGIC;
       a, b: in STD_LOGIC;
       y: out STD_LOGIC);
end;

architecture synth of fsm2 is
  type statetype is (S0, S1, S2, S3);
  signal state, nextstate: statetype;
begin
  process(clk, reset) begin
    if reset then state <= S0;
    elsif rising_edge(clk) then
      state <= nextstate;
    end if;
  end process;

  process(all) begin
    case state is
      when S0 => if (a xor b) then
                    nextstate <= S1;
                 else nextstate <= S0;
                 end if;
      when S1 => if (a and b) then
                    nextstate <= S2;
                 else nextstate <= S0;
                 end if;
      when S2 => if (a or b) then
                    nextstate <= S3;
                 else nextstate <= S0;
                 end if;
      when S3 => if (a or b) then
                    nextstate <= S3;
                 else nextstate <= S0;
                 end if;
      end case;
  end process;

  y <= '1' when ((state = S1) or (state = S2))
       else '0';
end;

**Bài tập 4.25** Hãy vẽ sơ đồ chuyển trạng thái (state transition diagram) cho máy trạng thái hữu hạn (FSM) được mô tả bởi đoạn mã HDL dưới đây. Một FSM thuộc loại này thường được sử dụng trong bộ dự đoán nhánh (branch predictor) trên một số vi xử lý.

---

### **SystemVerilog**
module fsm1(input  logic clk, reset,
            input  logic taken, back,
            output logic predicttaken);

  logic [4:0] state, nextstate;

  parameter S0 = 5'b00001;
  parameter S1 = 5'b00010;
  parameter S2 = 5'b00100;
  parameter S3 = 5'b01000;
  parameter S4 = 5'b10000;

  always_ff @(posedge clk, posedge reset)
    if (reset) state <= S2;
    else       state <= nextstate;

  always_comb
    case (state)
      S0: if (taken) nextstate = S1;
          else       nextstate = S0;
      S1: if (taken) nextstate = S2;
          else       nextstate = S0;
      S2: if (taken) nextstate = S3;
          else       nextstate = S1;
      S3: if (taken) nextstate = S4;
          else       nextstate = S2;
      S4: if (taken) nextstate = S4;
          else       nextstate = S3;
      default:       nextstate = S2;
    endcase

  assign predicttaken = (state == S4) |
                        (state == S3) |
                        (state == S2 & back);
endmodule

---

### **VHDL**
library IEEE; use IEEE.STD_LOGIC_1164.all;

entity fsm1 is
  port(clk, reset: in  STD_LOGIC;
       taken, back: in  STD_LOGIC;
       predicttaken: out STD_LOGIC);
end;

architecture synth of fsm1 is
  type statetype is (S0, S1, S2, S3, S4);
  signal state, nextstate: statetype;
begin
  process(clk, reset) begin
    if reset then state <= S2;
    elsif rising_edge(clk) then
      state <= nextstate;
    end if;
  end process;

  process(all) begin
    case state is
      when S0 => if taken then
                   nextstate <= S1;
                 else nextstate <= S0;
                 end if;
      when S1 => if taken then
                   nextstate <= S2;
                 else nextstate <= S0;
                 end if;
      when S2 => if taken then
                   nextstate <= S3;
                 else nextstate <= S1;
                 end if;
      when S3 => if taken then
                   nextstate <= S4;
                 else nextstate <= S2;
                 end if;
      when S4 => if taken then
                   nextstate <= S4;
                 else nextstate <= S3;
                 end if;
      when others => nextstate <= S2;
    end case;
  end process;

  -- output logic
  predicttaken <= '1' when
                  ((state = S4) or (state = S3) or
                   (state = S2 and back = '1'))
                  else '0';
end;

